const timespan = require('./lib/timespan');
const PS_SUPPORTED = require('./lib/psSupported');
const validateAsymmetricKey = require('./lib/validateAsymmetricKey');
const jws = require('jws');
const _ = require('lodash');
const { KeyObject, createSecretKey, createPrivateKey } = require('crypto');

const SUPPORTED_ALGS = ['RS256', 'RS384', 'RS512', 'ES256', 'ES384', 'ES512', 'HS256', 'HS384', 'HS512', 'none'];

if (PS_SUPPORTED) {
  SUPPORTED_ALGS.splice(3, 0, 'PS256', 'PS384', 'PS512');
}

const sign_options_schema = {
  expiresIn: { 
    isValid: (value) => _.isInteger(value) || _.isString(value), 
    message: '"expiresIn" should be a number of seconds or string representing a timespan' 
  },
  notBefore: { 
    isValid: (value) => _.isInteger(value) || _.isString(value), 
    message: '"notBefore" should be a number of seconds or string representing a timespan' 
  },
  audience: { 
    isValid: (value) => _.isString(value) || Array.isArray(value), 
    message: '"audience" must be a string or array' 
  },
  algorithm: { 
    isValid: (value) => SUPPORTED_ALGS.includes(value), 
    message: '"algorithm" must be a valid string enum value' 
  },
  header: { isValid: _.isPlainObject, message: '"header" must be an object' },
  encoding: { isValid: _.isString, message: '"encoding" must be a string' },
  issuer: { isValid: _.isString, message: '"issuer" must be a string' },
  subject: { isValid: _.isString, message: '"subject" must be a string' },
  jwtid: { isValid: _.isString, message: '"jwtid" must be a string' },
  noTimestamp: { isValid: _.isBoolean, message: '"noTimestamp" must be a boolean' },
  keyid: { isValid: _.isString, message: '"keyid" must be a string' },
  mutatePayload: { isValid: _.isBoolean, message: '"mutatePayload" must be a boolean' },
  allowInsecureKeySizes: { isValid: _.isBoolean, message: '"allowInsecureKeySizes" must be a boolean' },
  allowInvalidAsymmetricKeyTypes: { isValid: _.isBoolean, message: '"allowInvalidAsymmetricKeyTypes" must be a boolean' }
};

const registered_claims_schema = {
  iat: { isValid: _.isNumber, message: '"iat" should be a number of seconds' },
  exp: { isValid: _.isNumber, message: '"exp" should be a number of seconds' },
  nbf: { isValid: _.isNumber, message: '"nbf" should be a number of seconds' }
};

function validate(schema, allowUnknown, object, parameterName) {
  if (!_.isPlainObject(object)) {
    throw new Error(`Expected "${parameterName}" to be a plain object.`);
  }
  Object.keys(object).forEach((key) => {
    const validator = schema[key];
    if (!validator) {
      if (!allowUnknown) {
        throw new Error(`"${key}" is not allowed in "${parameterName}"`);
      }
      return;
    }
    if (!validator.isValid(object[key])) {
      throw new Error(validator.message);
    }
  });
}

function validateOptions(options) {
  return validate(sign_options_schema, false, options, 'options');
}

function validatePayload(payload) {
  return validate(registered_claims_schema, true, payload, 'payload');
}

const options_to_payload = {
  audience: 'aud',
  issuer: 'iss',
  subject: 'sub',
  jwtid: 'jti'
};

const options_for_objects = ['expiresIn', 'notBefore', 'noTimestamp', 'audience', 'issuer', 'subject', 'jwtid'];

module.exports = function (payload, secretOrPrivateKey, options, callback) {
  if (typeof options === 'function') {
    callback = options;
    options = {};
  } else {
    options = options || {};
  }

  const isObjectPayload = typeof payload === 'object' && !Buffer.isBuffer(payload);

  const header = {
    alg: options.algorithm || 'HS256',
    typ: isObjectPayload ? 'JWT' : undefined,
    kid: options.keyid,
    ...options.header
  };

  function failure(err) {
    if (callback) {
      return callback(err);
    }
    throw err;
  }

  if (!secretOrPrivateKey && options.algorithm !== 'none') {
    return failure(new Error('secretOrPrivateKey must have a value'));
  }

  if (secretOrPrivateKey && !(secretOrPrivateKey instanceof KeyObject)) {
    try {
      secretOrPrivateKey = createPrivateKey(secretOrPrivateKey);
    } catch (_) {
      try {
        secretOrPrivateKey = createSecretKey(Buffer.isBuffer(secretOrPrivateKey) ? secretOrPrivateKey : Buffer.from(secretOrPrivateKey));
      } catch (_) {
        return failure(new Error('secretOrPrivateKey is not valid key material'));
      }
    }
  }

  if (header.alg.startsWith('HS') && secretOrPrivateKey.type !== 'secret') {
    return failure(new Error(`secretOrPrivateKey must be a symmetric key when using ${header.alg}`));
  } else if (/^(?:RS|PS|ES)/.test(header.alg) && secretOrPrivateKey.type !== 'private') {
    return failure(new Error(`secretOrPrivateKey must be an asymmetric key when using ${header.alg}`));
  }

  if (!options.allowInvalidAsymmetricKeyTypes) {
    try {
      validateAsymmetricKey(header.alg, secretOrPrivateKey);
    } catch (error) {
      return failure(error);
    }
  }

  const timestamp = payload.iat || Math.floor(Date.now() / 1000);
  if (options.noTimestamp) delete payload.iat;
  else if (isObjectPayload) payload.iat = timestamp;

  if (typeof options.expiresIn !== 'undefined') {
    try {
      payload.exp = timespan(options.expiresIn, timestamp);
    } catch (err) {
      return failure(err);
    }
  }

  Object.keys(options_to_payload).forEach((key) => {
    if (options[key] && !payload[options_to_payload[key]]) {
      payload[options_to_payload[key]] = options[key];
    }
  });

  const encoding = options.encoding || 'utf8';

  if (typeof callback === 'function') {
    callback = _.once(callback);
    jws.createSign({
      header,
      privateKey: secretOrPrivateKey,
      payload,
      encoding
    }).once('error', callback)
      .once('done', (signature) => callback(null, signature));
  } else {
    return jws.sign({ header, payload, secret: secretOrPrivateKey, encoding });
  }
};
